const lessons=[life,structures,states,errors,testing,plans,data,maintenance,amendments];
export function authorSection12Lesson(source){
 if(source.section===12){const authored=lessons[source.originalLesson-81];if(!authored)throw new Error(`Missing S12 lesson ${source.originalLesson}`);return {...source,...authored,objectives:source.objectives.map(([id,text])=>[id,id==='S12.05.A09'?'Select a testing method and appropriate test data for a given scenario.':text]),summaryMode:'authored',sources:['Cambridge 9618 2027–2029 syllabus, sections 12.1–12.3: https://www.cambridgeinternational.org/Images/721397-2027-2029-syllabus.pdf','Cambridge 9618 2027–2029 pseudocode guide: https://www.cambridgeinternational.org/Images/721401-2027-2029-pseudocode-guide.pdf','Original teaching scenarios, diagrams, questions and marking points.']};}
 if(source.kind!=='review'||source.paper!==2)return source;
 const r=(...ns)=>ns.map(n=>`S12.${String(n).padStart(2,'0')}.R`);
 const review=unit('REVIEW','Section 12: Software development',r(1,2,3,4,5,6,7,8,9),[
  'Connect each development decision to observable evidence: requirements and project constraints guide the life cycle; a hierarchy and labelled interfaces guide implementation; states and transitions document event-dependent behaviour. Use a trace to check that the resulting algorithm implements the intended rules.',
  'Choose tests for the risks being examined and record their expected results before running them. After delivery, identify why a change is needed, analyse its impact, make the requested amendment and check both changed and preserved behaviour. A category name alone cannot demonstrate any of these practical skills.',
 ],[table('S12 review route',['Focus','Evidence to produce'],[['Life cycle','Model choice linked to requirement stability and user access'],['Structure chart','Hierarchy, transferred values and matching pseudocode'],['State transitions','States reached from an initial state by named events'],['Errors','Located cause, correction and retest'],['Testing methods','Method selected for the required evidence'],['Strategy and plan','Overall approach plus recorded cases and outcomes'],['Test data','Values tied to limits with expected results'],['Maintenance','Category justified by the cause of the change'],['Amendment','Working enhancement that preserves existing results']])], 'Correct vocabulary is not enough when a task asks for a chart, a trace or an amended program.', 'Which evidence checks that an enhancement preserved the old calculation?','Run the old and amended programs on the same cases and compare their original outputs with independently expected results.');
 review.syllabusId='REVIEW-2-4';
 review.summary=['Section 12: Software development','Select a life cycle; interpret and construct charts; diagnose errors; plan tests and select data; classify maintenance and verify an amended program.'];
 const practice=[
  question('REV-P2-S12-Q1','A club has changing booking requirements and members who can review prototypes weekly. Explain a suitable life cycle. A diagram starts Idle and changes to Booking on begin, then to Idle on cancel. State the states reached after begin, cancel.',r(1,3),['Iterative development or RAD can use the available reviews to refine working booking behaviour.','The choice needs control of changing requirements and successive versions.','The two events lead to Booking and then Idle.'],'Do not confuse the event-state diagram with module decomposition.'),
  question('REV-P2-S12-Q2','A parent calls GetScore, DecideAward and ShowAward. GetScore returns a score to the parent; DecideAward receives it and returns an award label; ShowAward displays the label. Describe the interface directions and a suitable integration test, then identify why a display-library update for a new operating system is needed.',r(2,5,8),['Score flows from GetScore to the parent and from the parent to DecideAward.','The award label returns to the parent and is passed into ShowAward.','A known score with an independently expected award checks the connected modules\' data and result.','The operating-system change requires adaptive maintenance because an external interface changed.'],'Follow values through the caller rather than inventing direct child-to-child calls.'),
  question('REV-P2-S12-Q3','A field accepts integer ages 12–18 inclusive, but 18 is rejected. Give a likely boundary fault and three tests around that upper limit with expected outcomes. Explain how the test plan and test strategy contribute to checking the correction.',r(4,6,7),['A strict upper comparison such as Age < 18 could cause the observed defect and should be checked in the code.','17 and 18 should be accepted; 19 should be rejected.','The plan records those inputs, expectations, actual results and outcomes for the corrected build.','The strategy assigns the method, responsibility and sequence for the correction and related regression checks.'],'The observed rejection suggests a cause; inspect the code before declaring the exact fault.'),
  question('REV-P2-S12-Q4','Write an amended version of the supplied three-day rainfall program to count WetDays for positive rainfall while retaining Total. State the outputs for 0, 2.0, 0.5 and why zero rainfall belongs in the tests.',r(9,7),['Declare and initialise an INTEGER WetDays before the loop.','Increment it inside IF Rain > 0.0 and output it after Total.','The supplied data give Total 2.5 and WetDays 2.','Zero verifies that a dry day does not enter the new count.'],'Preserve the original accumulation for every day.',{...supplied('rainOriginal'),...solution('rainEnhanced')}),
 ];
 return {...source,units:source.units.map(u=>u.heading.startsWith('Section 12:')?review:u),practice:[...source.practice.filter(p=>p.id!=='V3-Q-L090-04'),...practice]};
}
